#include "mutation5.h"
#include <stdio.h>
#include <string.h>
#include <limits.h>
static int ab(int x){return x<0?-x:x;}
static int pc(int x){x%=12;return x<0?x+12:x;}
static int clamp(int x,int a,int b){return x<a?a:x>b?b:x;}
static uint32_t rng(uint32_t *s){uint32_t x=*s;if(!x)x=0x9e3779b9u;x^=x<<13;x^=x>>17;x^=x<<5;return *s=x;}
static const int modes[5][7]={{0,2,3,5,7,8,10},{0,2,3,5,7,9,10},{0,1,3,5,7,8,10},{0,2,3,5,7,8,11},{0,2,4,5,7,9,11}};
static const char *names[M5_WEIGHTS]={"scale_strong","chord_strong","intervals","density","syncopation","closure","tension","expectation","fit","similarity","register","offbeat"};
static int group(int kind,int speed,int fit){return (kind*4+clamp(speed,0,3))*4+clamp(fit,0,3);}
uint32_t m5_context_size(void){return (uint32_t)sizeof(m5_context);}
uint32_t m5_model_size(void){return (uint32_t)sizeof(m5_model);}
int m5_load_weights(m5_context *c,const char *path){FILE *f;char line[256],key[80],extra;int value,seen[M5_WEIGHTS]={0},i;if(!c||!path)return -1;f=fopen(path,"r");if(!f)return -2;while(fgets(line,sizeof(line),f)){if(line[0]=='#'||line[0]=='\n'||line[0]=='\r')continue;if(sscanf(line,"%79s %d %c",key,&value,&extra)!=2||value<0||value>100000){fclose(f);return -3;}for(i=0;i<M5_WEIGHTS;i++)if(!strcmp(key,names[i]))break;if(i==M5_WEIGHTS||seen[i]){fclose(f);return -4;}seen[i]=1;c->weights[i]=value;}fclose(f);for(i=0;i<M5_WEIGHTS;i++)if(!seen[i])return -5;return 0;}
int m5_load(m5_context *c,const char *path,const char *weights){FILE *f;char magic[8];uint32_t a,b;if(!c||!path)return -1;f=fopen(path,"rb");if(!f)return -2;if(fread(magic,1,8,f)!=8||memcmp(magic,"TTMM5V01",8)||fread(&a,4,1,f)!=1||fread(&b,4,1,f)!=1||a!=offsetof(m3_context,back)||b!=sizeof(m5_model)){fclose(f);return -3;}if(fread(&c->proposal,1,a,f)!=a||fread(&c->model,1,b,f)!=b||fgetc(f)!=EOF){fclose(f);return -4;}fclose(f);if(c->model.count<1||c->model.count>M5_ROWS||c->proposal.pattern_count<1||c->proposal.pattern_count>M3_PATTERNS)return -5;return m5_load_weights(c,weights);}
void m5_features(m5_context *c,const m3_phrase *b,const m3_phrase *w,int32_t *f){int i,j,strong=0,scale=0;int64_t sim=0,rhythm=0;uint32_t sm=0;memset(f,0,M5_FEATURES*sizeof(*f));m3_features(&c->proposal,b,w,f);for(j=0;j<7;j++)sm|=1u<<pc(b->key+modes[b->mode][j]);for(i=0;i<w->count;i++){int p=w->notes[i].pitch;if(w->notes[i].start%(c->bar/2)==0){strong++;scale+=(sm>>pc(p))&1u;}j=i*b->count/w->count;sim+=ab(p-b->notes[j].pitch);rhythm+=ab(w->notes[i].start-b->notes[j].start)+ab(w->notes[i].duration-b->notes[j].duration);if(i)f[18+clamp(p-w->notes[i-1].pitch,-15,15)+15]++;}f[12]=strong?scale*1000/strong:0;f[13]=(int32_t)((int64_t)w->count*c->bar*1000/w->length);j=pc(w->notes[w->count-1].pitch-b->key);f[14]=(j<12-j?j:12-j)*1000;f[15]=(int32_t)((int64_t)(w->length-w->notes[w->count-1].start-w->notes[w->count-1].duration)*1000/w->length);f[16]=(int32_t)(sim*1000/w->count);f[17]=(int32_t)(rhythm*1000/w->count/960);for(i=18;i<M5_FEATURES;i++)f[i]=w->count>1?f[i]*1000/(w->count-1):0;}
static int spread(m5_context *c,int i){int g=c->group%16;return c->kind==2?c->model.spread[c->group][i]:(int)(((int64_t)c->model.spread[g][i]*(1000-c->dark)+(int64_t)c->model.spread[g+16][i]*c->dark)/1000);}
static int bound(m5_context *c,int i,int high){int g=group(c->kind,3,c->fit);int32_t (*a)[2]=high?c->model.maximum:c->model.minimum;return c->kind==2?a[g][i]:(int)(((int64_t)a[12+c->fit][i]*(1000-c->dark)+(int64_t)a[28+c->fit][i]*c->dark)/1000);}
static int category(int i){if(i>=18)return 2;switch(i){case 0:return 6;case 1:case 2:case 3:return 7;case 4:case 5:case 6:return 8;case 7:case 9:return 10;case 8:return 1;case 10:return 11;case 11:return 4;case 12:return 0;case 13:return 3;case 14:case 15:return 5;default:return 9;}}
int64_t m5_score(m5_context *c,const m3_phrase *b,const m3_phrase *w){int32_t f[M5_FEATURES];int64_t score=0,parts[M5_WEIGHTS]={0};int i;m5_features(c,b,w,f);for(i=0;i<M5_FEATURES;i++){int cat=category(i);int64_t target=c->target[i],sd=spread(c,i);if(i==16||i==17){target=target*c->intensity/1000;sd=sd*c->intensity/1000;}if(sd<1)sd=1;parts[cat]+=(int64_t)ab(f[i]-(int)target)*1000/sd;}parts[2]/=31;parts[5]/=2;parts[7]/=3;parts[8]/=3;parts[9]/=2;parts[10]/=2;for(i=0;i<M5_WEIGHTS;i++)score+=parts[i]*c->weights[i];return score;}
static void select_target(m5_context *c,const m3_phrase *b){int i,pass,best=INT_MAX,n=0,pick,fit=clamp(c->fit,0,3);for(pass=0;pass<4;pass++){best=INT_MAX;n=0;for(i=0;i<c->model.count;i++){const m5_row *r=&c->model.rows[i];int d;if(r->kind!=c->kind||(pass<2&&r->fit!=fit)||((pass==0||pass==2)&&r->speed!=b->speed))continue;d=ab(r->count-b->count);if(d<best){best=d;n=0;}if(d==best)n++;}if(n)break;}pick=n?(int)(rng(&c->seed)%(uint32_t)n):0;for(i=0;i<c->model.count;i++){const m5_row *r=&c->model.rows[i];if(r->kind!=c->kind||(pass<2&&r->fit!=fit)||((pass==0||pass==2)&&r->speed!=b->speed)||ab(r->count-b->count)!=best)continue;if(!pick--){memcpy(c->target,r->features,sizeof(c->target));break;}}c->group=group(c->kind,b->speed,fit);}
static void velocities(m5_context *c,m3_phrase *w){int i;for(i=0;i<w->count;i++){int pos=(int)((int64_t)(w->notes[i].start%c->bar)*16/c->bar),j;int64_t z=0;for(j=0;j<12;j++)z+=(int)(rng(&c->seed)%2001)-1000;/* sd of sum of 12 U[-1000,1000] is about 2000. */{int64_t mean=c->model.velocity_mean[c->kind][pos],sd=c->model.velocity_sd[c->kind][pos];if(c->kind!=2){mean=((int64_t)c->model.velocity_mean[0][pos]*(1000-c->dark)+(int64_t)c->model.velocity_mean[1][pos]*c->dark)/1000;sd=((int64_t)c->model.velocity_sd[0][pos]*(1000-c->dark)+(int64_t)c->model.velocity_sd[1][pos]*c->dark)/1000;}z=z*sd/2000+mean;}w->notes[i].velocity=clamp(w->notes[i].velocity+(int)(z*c->intensity/1000000),1,127);}}
void m5_refresh(m3_phrase *w){int i,j;for(i=0;i<w->count;i++){w->notes[i].chord=0;for(j=0;j<w->chord_count;j++)if(w->chords[j].start<=w->notes[i].start&&w->notes[i].start<w->chords[j].end){w->notes[i].chord=w->chords[j].mask;break;}}}
static int fit_penalty(m5_context *c,const int32_t *f){int i;int64_t v=0;for(i=0;i<2;i++){int z=f[4+i],lo=bound(c,i,0),hi=bound(c,i,1),sd=spread(c,4+i);int d=z<lo?lo-z:z>hi?z-hi:0;v+=(int64_t)d*1000/(sd>0?sd:1);}return (int)v;}
/* Templates are diatonic stacks of thirds (triad, seventh, ninth). Existing
 voices are moved minimally; no generic harmony model or bass rewrite. */
static int voice(m3_chord *ch,uint32_t mask){
 int original[16],i,j,p,total=0;uint32_t got=0;
 for(i=0;i<ch->count;i++)original[i]=ch->pitches[i];
 for(i=0;i<ch->count;i++){
  int best=-1,dist=999;
  for(p=0;p<128;p++)if(mask&(1u<<pc(p))){int used=0,d=ab(p-original[i]);for(j=0;j<i;j++)used|=ch->pitches[j]==p;if(!used&&d<dist){dist=d;best=p;}}
  if(best<0)return -1;ch->pitches[i]=best;got|=1u<<pc(best);
 }
 for(p=0;p<12;p++)if((mask&(1u<<p))&&!(got&(1u<<p))){
  int bi=-1,bp=0,bd=INT_MAX;
  for(i=0;i<ch->count;i++){int q,ct=0;for(j=0;j<ch->count;j++)ct+=pc(ch->pitches[j])==pc(ch->pitches[i]);if(ct<2)continue;
   for(q=p;q<128;q+=12){int used=0,d=ab(q-original[i])-ab(ch->pitches[i]-original[i]);for(j=0;j<ch->count;j++)if(j!=i)used|=ch->pitches[j]==q;if(!used&&d<bd){bd=d;bp=q;bi=i;}}
  }
  if(bi<0)return -1;ch->pitches[bi]=bp;got|=1u<<p;
 }
 for(i=0;i<ch->count;i++)total+=ab(ch->pitches[i]-original[i]);
 for(i=1;i<ch->count;i++){int q=ch->pitches[i],j=i;while(j&&ch->pitches[j-1]>q){ch->pitches[j]=ch->pitches[j-1];j--;}ch->pitches[j]=q;}
 ch->mask=mask;return total;
}
static int window(m5_context *c,const m3_phrase *w,int start,int end,uint32_t mask,int root,uint32_t *oldmask){int j,n=0,cost=0;*oldmask=0;if(w->chord_count>508)return -1;c->trial=*w;c->trial.chord_count=0;for(j=0;j<w->chord_count;j++){m3_chord ch=w->chords[j];int a=ch.start>start?ch.start:start,z=ch.end<end?ch.end:end,rc;if(z<=a){c->trial.chords[c->trial.chord_count++]=ch;continue;}*oldmask|=ch.mask;if(ch.start<a){m3_chord left=ch;left.end=a;c->trial.chords[c->trial.chord_count++]=left;}if(ch.end>z){m3_chord right=ch;right.start=z;c->trial.chords[c->trial.chord_count++]=right;}ch.start=a;ch.end=z;rc=voice(&ch,mask);if(rc<0)return -1;cost+=rc;n++;c->trial.chords[c->trial.chord_count++]=ch;if(c->trial.chord_count>510)return -1;}if(!n)return -1;m5_refresh(&c->trial);for(j=0;j<c->trial.count;j++)if(start<=c->trial.notes[j].start&&c->trial.notes[j].start<end)c->trial.notes[j].root=root;return cost;}
static void harmony(m5_context *c,const m3_phrase *b,m3_phrase *w){int32_t f[M5_FEATURES],g[M5_FEATURES];int start,pass,degree,tones,bestpen,bestmove=INT_MAX,found=0;int selected_start=0,selected_end=0,selected_root=0;uint32_t selected_old=0,selected_new=0;m5_features(c,b,w,f);memset(&c->notice,0,sizeof(c->notice));c->notice.ct_before=f[4];c->notice.pcs_before=f[5];c->notice.ct_after=f[4];c->notice.pcs_after=f[5];c->notice.gate_ct_out=f[4]<bound(c,0,0)||f[4]>bound(c,0,1);c->notice.gate_pcs_out=f[5]<bound(c,1,0)||f[5]>bound(c,1,1);if(!c->notice.gate_ct_out||!c->notice.gate_pcs_out)return;bestpen=fit_penalty(c,f);c->notice.penalty_before=bestpen;c->notice.penalty_after=bestpen;
 for(pass=0;pass<2&&!found;pass++)for(start=0;start<w->length;start+=c->bar/2){int end=start+c->bar/2,oldroot=-1,i;if(end>w->length)end=w->length;for(i=0;i<w->count;i++)if(start<=w->notes[i].start&&w->notes[i].start<end&&w->notes[i].chord){oldroot=w->notes[i].root;break;}if(oldroot<0)continue;for(degree=0;degree<7;degree++){int root=pc(w->key+modes[w->mode][degree]);if(pass==0&&root!=oldroot)continue;for(tones=3;tones<=5;tones++){uint32_t mask=0,oldmask;int j,move,pen;for(j=0;j<tones;j++)mask|=1u<<pc(w->key+modes[w->mode][(degree+j*2)%7]);move=window(c,w,start,end,mask,root,&oldmask);if(move<0||oldmask==mask)continue;m5_features(c,b,&c->trial,g);pen=fit_penalty(c,g);/* Only strict improvement in empirical out-of-range penalty, then minimum movement. */if(pen>=c->notice.penalty_before)continue;if(!found||move<bestmove||(move==bestmove&&pen<bestpen)){found=1;bestmove=move;bestpen=pen;c->best=c->trial;selected_start=start;selected_end=end;selected_root=root==oldroot;selected_old=oldmask;selected_new=mask;}}}}
 if(found){*w=c->best;m5_features(c,b,w,g);c->notice.changed=1;c->notice.start=selected_start;c->notice.end=selected_end;c->notice.old_mask=(int)selected_old;c->notice.new_mask=(int)selected_new;c->notice.root_preserved=selected_root;c->notice.ct_after=g[4];c->notice.pcs_after=g[5];c->notice.penalty_after=bestpen;}}
int m5_generate(m5_context *c,const m3_phrase *b,const m5_params *p,m3_phrase *out,m5_notice *notice){m3_params q;int rc,i;int32_t light[M5_FEATURES];if(!c||!b||!p||!out||!notice||p->fit<0||p->fit>3||p->bar_ticks<2||p->harmony<0||p->harmony>1)return -1;c->bar=p->bar_ticks;c->fit=p->fit;c->kind=p->operation==1?2:p->dark>=500?1:0;c->intensity=p->intensity;c->dark=p->dark;c->seed=m3_pad_seed(p->seed,31);memset(&c->notice,0,sizeof(c->notice));q.seed=p->seed;q.operation=p->operation;q.intensity=p->intensity;q.dark=p->dark;q.candidates=p->candidates;q.passes=p->passes;if(p->operation==1){select_target(c,b);}else{c->kind=0;select_target(c,b);memcpy(light,c->target,sizeof(light));c->kind=1;select_target(c,b);for(i=0;i<M5_FEATURES;i++)c->target[i]=(int32_t)(((int64_t)light[i]*(1000-p->dark)+(int64_t)c->target[i]*p->dark)/1000);c->kind=p->dark>=500?1:0;c->group=group(c->kind,b->speed,c->fit);}rc=m5_propose(&c->proposal,b,&q,out,c);if(rc<0)return rc;if(p->intensity&&!(p->operation==1&&(rc&M3_NO_COMPATIBLE_RHYTHM))){velocities(c,out);m5_refresh(out);if(p->harmony)harmony(c,b,out);}*notice=c->notice;return rc;}
